 "content": "def transform(grid):
    """Color every zero-valued translation of the 8-cell pattern with 8."""
    h, w = len(grid), len(grid[0])
    pattern = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 8]
    if not pattern:
        return [row[:] for row in grid]
    min_r = min(r for r, _ in pattern)
    min_c = min(c for _, c in pattern)
    shape = [(r - min_r, c - min_c) for r, c in pattern]
    max_r = max(r for r, _ in shape)
    max_c = max(c for _, c in shape)
    out = [row[:] for row in grid]
    for r0 in range(h - max_r):
        for c0 in range(w - max_c):
            cells = [(r0 + dr, c0 + dc) for dr, dc in shape]
            if all(grid[r][c] == 0 for r, c in cells):
                for r, c in cells:
                    out[r][c] = 8
    return out
